function analysis_envelope_spectrum_main(args)
% Dataset-native envelope spectrum analysis.
% SPDX-License-Identifier: GPL-3.0-or-later
  module_id='analysis.envelope_spectrum';module_version='1.1.0';chunk_rows=65536;pub_chunk=65536;
  P=struct();Q=struct();p_open=false;p_final=false;q_open=false;q_final=false;
  this_file=mfilename('fullpath');runtime_dir=fileparts(this_file);module_dir=fileparts(runtime_dir);modules_dir=fileparts(module_dir);plugins_dir=fileparts(modules_dir);package_root=fileparts(plugins_dir);
  config_path=arg_value(args,'--config','');if(isempty(config_path)),error('%s: --config is required',module_id);endif;cfg=gxtxt_ini_read(config_path);outdir=strtrim(gxtxt_ini_get(cfg,'runtime.output_dir',''));session=strtrim(gxtxt_ini_get(cfg,'runtime.session',''));if(isempty(outdir)||isempty(session)),error('%s: runtime output/session information missing',module_id);endif;if(exist(outdir,'dir')!=7),mkdir(outdir);endif
  gxtxt_progress_start('prepare','Preparing envelope spectrum analysis','indeterminate');
  try
    numeric=discover_numeric_api(cfg,module_id);discover_plot_service(package_root,module_id);
    ds=strtrim(gxtxt_ini_get(cfg,'analysis_source.primary.dataset_id',''));if(isempty(ds)),ds=strtrim(gxtxt_ini_get(cfg,'dataset.id',''));endif;if(isempty(ds)),error('%s: source Dataset ID missing',module_id);endif
    tb=binding_name(gxtxt_ini_get(cfg,'bindings.time',''));sb=binding_name(gxtxt_ini_get(cfg,'bindings.signal',''));if(isempty(tb)||isempty(sb)),error('%s: time and signal bindings are required',module_id);endif
    [tu,~,tm]=gxtxt_analysis_source_variable_meta(cfg,'primary',tb);[su,~,sm]=gxtxt_analysis_source_variable_meta(cfg,'primary',sb);require_meta(tm,'time',module_id);require_meta(sm,'signal',module_id);tid=strtrim(tm.variable_id);sid=strtrim(sm.variable_id);sname=strtrim(sm.name);if(isempty(sname)),sname=sid;endif
    M=gxtxt_table_stream_open_source(cfg,'primary',{tid,sid},1,struct('start',0,'count',0,'require_direct',false));row_count=M.row_count;schema=M.schema;provider=M.storage_provider;M=gxtxt_table_stream_close(M);ts=find_schema(schema,tid);if(isempty(ts)),error('%s: time variable absent from schema',module_id);endif
    selection=struct('enabled',false);try selection=gxtxt_selection_from_runtime(cfg,'selection');catch e,error('%s: invalid Dataset Selection: %s',module_id,e.message);end_try_catch;if(selection.enabled),validate_selection(selection,ds,tid);endif
    input_detrend=lower(strtrim(gxtxt_ini_get(cfg,'config.input_detrend','mean')));filter_mode=lower(strtrim(gxtxt_ini_get(cfg,'config.demodulation_filter','none')));low=str2double(strtrim(gxtxt_ini_get(cfg,'config.band_low_hz','1500')));high=str2double(strtrim(gxtxt_ini_get(cfg,'config.band_high_hz','2600')));envelope_dc=lower(strtrim(gxtxt_ini_get(cfg,'config.envelope_dc','remove_mean')));window_name=lower(strtrim(gxtxt_ini_get(cfg,'config.window','hann')));nfft_mode=lower(strtrim(gxtxt_ini_get(cfg,'config.nfft_mode','auto')));
    if(!any(strcmp(input_detrend,{'none','mean','linear'}))),error('%s: invalid input detrend',module_id);endif;if(!any(strcmp(filter_mode,{'none','ideal_fft_bandpass'}))),error('%s: invalid demodulation filter',module_id);endif;if(!any(strcmp(envelope_dc,{'keep','remove_mean'}))),error('%s: invalid envelope DC mode',module_id);endif;if(!any(strcmp(window_name,{'rectangular','hann','hamming','blackman','blackman_harris','flat_top'}))),error('%s: invalid FFT window',module_id);endif
    axis_kind=lower(strtrim(ts.axis_kind));origin=str2double(strtrim(ts.axis_origin));step=str2double(strtrim(ts.axis_step));uniform=strcmp(axis_kind,'uniform')&&isfinite(origin)&&isfinite(step)&&step>0;
    if(uniform)
      [start0,count]=uniform_range(selection,origin,step,row_count);dt_native=step;t0_native=origin+start0*step;
    else
      [t,x]=load_explicit(cfg,tid,sid,selection,chunk_rows);if(numel(t)<4),error('%s: selected interval contains fewer than 4 samples',module_id);endif
      G=feval(numeric.function_name,'grid_info',t,struct('rtol',1e-6,'atol',0,'nonfinite','error'));if(!G.strict_monotonic||!strcmp(G.direction,'increasing')||!G.uniform),error('%s: time variable is not uniformly sampled enough for envelope FFT processing (relative deviation %.6g)',module_id,G.relative_max_step_deviation);endif
      dt_native=G.step;t0_native=t(1);start0=0;count=numel(x);
    endif
    temporal_unit=strtrim(tu);if(isfield(tm,'value_kind')&&strcmpi(strtrim(tm.value_kind),'elapsed_time')),temporal_unit='s';endif;if(isempty(temporal_unit)),temporal_unit='s';endif
    try dt_seconds=gxtxt_unit_convert(dt_native,temporal_unit,'s');t0_seconds=gxtxt_unit_convert(t0_native,temporal_unit,'s');catch e,error('%s: time unit %s cannot convert to seconds: %s',module_id,temporal_unit,e.message);end_try_catch;fs=1/dt_seconds;
    if(uniform),gxtxt_progress_stage('load','Reading selected signal range','determinate',count);x=load_signal(cfg,sid,start0,count,chunk_rows);endif;if(numel(x)<4),error('%s: selected interval contains fewer than 4 samples',module_id);endif
    N=numel(x);if(strcmp(nfft_mode,'auto')),nfft=N;elseif(strcmp(nfft_mode,'explicit')),nfft=str2double(strtrim(gxtxt_ini_get(cfg,'config.nfft','')));if(!isfinite(nfft)||nfft!=fix(nfft)||nfft<N),error('%s: explicit NFFT must be an integer >= %d',module_id,N);endif;else error('%s: invalid NFFT mode',module_id);endif
    if(strcmp(filter_mode,'ideal_fft_bandpass')&&(low<=0||high<=low||high>=fs/2)),error('%s: bandpass must satisfy 0 < low < high < Nyquist (%g Hz)',module_id,fs/2);endif

    gxtxt_progress_stage('demodulate','Computing analytic envelope and envelope spectrum','indeterminate');R=envelope_compute(x,dt_seconds,input_detrend,filter_mode,low,high,envelope_dc,window_name,nfft,numeric.function_name);Nh=numel(R.frequency);psd_unit=make_psd_unit(su);
    spectrum_id=[safe_id(ds) '.envelope.' safe_id(sid)];envelope_id=[safe_id(ds) '.envelope_time.' safe_id(sid)];prov=sprintf('source_dataset=%s;time=%s;signal=%s;filter=%s;band_hz=%g..%g;envelope_dc=%s;window=%s;nfft=%d;module=%s@%s',ds,tid,sid,filter_mode,low,high,envelope_dc,window_name,nfft,module_id,module_version);

    options=struct('storage','auto','capabilities_required',{{'typed_numeric','implicit_axis','range_write'}},'capabilities_preferred',{{'sequential_chunks'}},'replace_owned',true,'producer_version',module_version,'source_dataset_ids',{{ds}},'source_variable_ids',{{tid,sid}},'source',ds,'provenance',prov,'notes','Analytic-signal envelope spectrum. Optional pre-demodulation isolation is an ideal zero-phase FFT bandpass.');
    P=gxtxt_publication_v2_open(session,module_id,spectrum_id,'spectrum.table',options);p_open=true;P=gxtxt_publication_v2_declare_dimension(P,'frequency_bin',Nh,false);P=gxtxt_publication_v2_declare_uniform(P,'frequency','frequency_bin',0,R.df,struct('name','frequency','unit','Hz','dtype','float64','semantic_role','independent'));
    vars={'envelope_amplitude',R.amplitude,su;'envelope_psd',R.psd,psd_unit;'envelope_psd_db',R.psd_db,'dB'};chunks=min(pub_chunk,Nh);for vi=1:size(vars,1),P=gxtxt_publication_v2_declare_variable(P,vars{vi,1},struct('dtype','float64','dimension_ids','frequency_bin','name',vars{vi,1},'unit',vars{vi,3},'semantic_role','measured','coordinate_variable_ids','frequency','chunks',chunks));endfor;for p0=0:pub_chunk:(Nh-1),cc=min(pub_chunk,Nh-p0);rr=(p0+1):(p0+cc);for vi=1:size(vars,1),P=gxtxt_publication_v2_write_range(P,vars{vi,1},p0,vars{vi,2}(rr));endfor;endfor;spectrum_provider=P.provider;[P,spectrum_result]=gxtxt_publication_v2_finalize(P);p_final=true;p_open=false;

    env_options=struct('storage','auto','capabilities_required',{{'typed_numeric','implicit_axis','range_write'}},'capabilities_preferred',{{'sequential_chunks'}},'replace_owned',true,'producer_version',module_version,'source_dataset_ids',{{ds}},'source_variable_ids',{{tid,sid}},'source',ds,'provenance',prov,'notes','Time-domain amplitude envelope produced by the analytic-signal demodulation workflow.');
    Q=gxtxt_publication_v2_open(session,module_id,envelope_id,'timeseries.table',env_options);q_open=true;Q=gxtxt_publication_v2_declare_dimension(Q,'sample',N,false);Q=gxtxt_publication_v2_declare_uniform(Q,'time','sample',t0_seconds,dt_seconds,struct('name','time','unit','s','dtype','float64','semantic_role','independent'));Q=gxtxt_publication_v2_declare_variable(Q,'envelope',struct('dtype','float64','dimension_ids','sample','name','Envelope','unit',su,'semantic_role','measured','coordinate_variable_ids','time','chunks',min(pub_chunk,N)));
    for p0=0:pub_chunk:(N-1),cc=min(pub_chunk,N-p0);rr=(p0+1):(p0+cc);Q=gxtxt_publication_v2_write_range(Q,'envelope',p0,R.envelope(rr));endfor;envelope_provider=Q.provider;[Q,envelope_result]=gxtxt_publication_v2_finalize(Q);q_final=true;q_open=false;

    D=struct('source_dataset_id',ds,'time_variable_id',tid,'signal_variable_id',sid,'signal_name',sname,'signal_unit',su,'sample_count',N,'fs',R.fs,'df',R.df,'nfft',R.nfft,'envelope_mean',R.envelope_mean,'envelope_rms',R.envelope_rms,'filter_mode',filter_mode,'band_low_hz',low,'band_high_hz',high,'window_name',window_name,'input_detrend',input_detrend,'envelope_dc',envelope_dc,'spectrum_dataset_id',spectrum_id,'envelope_dataset_id',envelope_id);
    write_report(fullfile(outdir,'envelope_spectrum_report.txt'),module_version,D,provider,spectrum_provider,envelope_provider,selection,spectrum_result,envelope_result);
    gxtxt_progress_stage('plot','Creating persistent plot.dataset graphs','indeterminate');graphs=create_standard_graphs(session,spectrum_id,envelope_id,su,psd_unit,module_id);copy_graph_artifacts(graphs,outdir,module_id);write_graph_manifest(fullfile(outdir,'automatic_graphs.ini'),graphs);
    gxtxt_progress_complete('done',sprintf('Published %s and %s',spectrum_id,envelope_id));
  catch err
    if(p_open&&!p_final),try P=gxtxt_publication_v2_abort(P);catch;end_try_catch;endif;if(q_open&&!q_final),try Q=gxtxt_publication_v2_abort(Q);catch;end_try_catch;endif;try gxtxt_progress_fail('failed',err.message);catch;end_try_catch;rethrow(err);
  end_try_catch
endfunction

function api=discover_numeric_api(cfg,module_id)
  sec='public_api.NUMERIC_API_v1';provider=strtrim(gxtxt_ini_get(cfg,[sec '.module_id'],''));if(!strcmp(provider,'math.numeric')),error('%s: runtime NUMERIC_API_v1 provider discovery failed',module_id);endif;if(!strcmp(strtrim(gxtxt_ini_get(cfg,[sec '.api_version'],'')),'1')),error('%s: unsupported runtime NUMERIC_API_v1 version',module_id);endif
  caps=split_list(gxtxt_ini_get(cfg,[sec '.capabilities'],''));required={'fft','ifft','analytic_signal','frequency_grid','one_sided_transform','detrending','window_generation','descriptive_statistics','grid_analysis'};for k=1:numel(required),if(!any(strcmp(caps,required{k}))),error('%s: NUMERIC_API_v1 capability missing: %s',module_id,required{k});endif,endfor
  entry_path=strtrim(gxtxt_ini_get(cfg,[sec '.octave_entrypoint'],''));fn=strtrim(gxtxt_ini_get(cfg,[sec '.octave_function'],''));if(isempty(entry_path)||isempty(fn)||exist(entry_path,'file')!=2),error('%s: runtime NUMERIC_API_v1 Octave binding is unavailable',module_id);endif;addpath(fileparts(entry_path));if(exist(fn,'file')!=2),error('%s: advertised NUMERIC_API_v1 function unavailable',module_id);endif;api=struct('function_name',fn,'provider',provider);
endfunction
function discover_plot_service(root,module_id),pd=fullfile(root,'plugins','modules','plot.dataset','module.ini');if(exist(pd,'file')!=2),error('%s: plot.dataset descriptor missing',module_id);endif;d=gxtxt_ini_read(pd);ids=split_list(gxtxt_ini_get(d,'public_apis.ids',''));if(!any(strcmp(ids,'PLOT_DATASET_API_v2'))),error('%s: PLOT_DATASET_API_v2 is not advertised',module_id);endif;bridge=fullfile(root,'core','octave','io','gxtxt_plot_dataset_v2.m');if(exist(bridge,'file')!=2),error('%s: public PLOT_DATASET_API_v2 Octave bridge unavailable',module_id);endif;addpath(fileparts(bridge));endfunction
function G=create_standard_graphs(session,spectrum_id,envelope_id,signal_unit,psd_unit,module_id)
  G={};G{end+1}=create_plot(session,spectrum_id,'envelope_spectrum','Envelope spectrum','frequency','envelope_amplitude','Frequency','Hz','Envelope amplitude',signal_unit,module_id);G{end+1}=create_plot(session,spectrum_id,'envelope_psd_db','Envelope power spectral density','frequency','envelope_psd_db','Frequency','Hz','Envelope PSD','dB',module_id);G{end+1}=create_plot(session,spectrum_id,'envelope_psd_linear','Envelope power spectral density','frequency','envelope_psd','Frequency','Hz','Envelope PSD',psd_unit,module_id);G{end+1}=create_plot(session,envelope_id,'envelope_time','Analytic-signal envelope','time','envelope','Time','s','Envelope',signal_unit,module_id);
endfunction
function R=create_plot(session,dataset_id,key,title_text,xvar,yvar,xlabel,xunit,ylabel,yunit,module_id)
  axes=struct('x',struct('label',axis_label(xlabel,xunit),'display_unit',xunit,'scale','linear'),'y_left',struct('label',axis_label(ylabel,yunit),'scale','linear'));series=struct('id',key,'dataset_id',dataset_id,'x_variable_id',xvar,'y_variable_id',yvar,'axis','left','kind','line','label',ylabel);panel=struct('id','main','title',title_text,'axes',axes,'series',{{series}});spec=struct('schema','PLOT_DATASET_PLOTSPEC_v2','graph_type','cartesian_2d','graph_id','plot.dataset.xy','title',title_text,'defaults',struct('style',struct()),'panels',{{panel}},'output',struct());R=gxtxt_plot_dataset_v2(session,spec,struct('action','create','kind','variant','source_variant','','render',true));if(!isfield(R,'artifact')||isempty(strtrim(R.artifact))),error('%s: plot.dataset returned no artifact for %s',module_id,key);endif;R.key=key;
endfunction
function copy_graph_artifacts(G,outdir,module_id),for i=1:numel(G),src=strtrim(G{i}.artifact);if(isempty(src)||exist(src,'file')!=2),error('%s: plot.dataset graph artifact missing for %s',module_id,G{i}.key);endif;dst=fullfile(outdir,sprintf('%02d_%s.png',i,G{i}.key));[ok,msg]=copyfile(src,dst,'f');if(!ok),error('%s: cannot copy plot.dataset artifact: %s',module_id,msg);endif;endfor;endfunction
function write_graph_manifest(path,G),fid=fopen(path,'w');if(fid<0),error('analysis.envelope_spectrum: cannot write automatic graph manifest');endif;unwind_protect fprintf(fid,'[automatic_graphs]\ncount=%d\nprovider=plot.dataset\napi=PLOT_DATASET_API_v2\npersistent_variants=true\n',numel(G));for i=1:numel(G),fprintf(fid,'\n[graph.%02d]\nkey=%s\ngraph_id=%s\nvariant_id=%s\npng=%02d_%s.png\nprovider_artifact=%s\nrerender=Use the persisted plot.dataset variant\n',i,G{i}.key,ini_escape(G{i}.graph_id),ini_escape(G{i}.variant_id),i,G{i}.key,ini_escape(G{i}.artifact));endfor;unwind_protect_cleanup fclose(fid);end_unwind_protect;endfunction
function [start0,count]=uniform_range(S,origin,step,nrows),start0=0;count=nrows;if(!S.enabled),return;endif;lo=min(S.x_min,S.x_max);hi=max(S.x_min,S.x_max);start0=max(0,ceil((lo-origin)/step-1e-12));last=min(nrows-1,floor((hi-origin)/step+1e-12));count=max(0,last-start0+1);endfunction
function x=load_signal(cfg,id,start0,count,chunk),S=gxtxt_table_stream_open_source(cfg,'primary',{id},chunk,struct('start',start0,'count',count,'require_direct',false,'numeric_transport','auto'));parts={};n=0;unwind_protect while(true),[S,C]=gxtxt_table_stream_v3_next(S);if(C.nrows>0),v=gxtxt_table_chunk_numeric(C,id);parts{end+1}=double(v(:));n+=C.nrows;endif;if(C.eof),break;endif;endwhile unwind_protect_cleanup S=gxtxt_table_stream_close(S);end_unwind_protect;if(n!=count),error('analysis.envelope_spectrum: source range returned %d rows; expected %d',n,count);endif;x=vertcat(parts{:});endfunction
function [t,x]=load_explicit(cfg,tid,sid,Ssel,chunk),S=gxtxt_table_stream_open_source(cfg,'primary',{tid,sid},chunk,struct('start',0,'count',-1,'require_direct',false,'numeric_transport','auto'));tp={};xp={};unwind_protect while(true),[S,C]=gxtxt_table_stream_v3_next(S);if(C.nrows>0),tv0=gxtxt_table_chunk_numeric(C,tid);xv0=gxtxt_table_chunk_numeric(C,sid);tv=double(tv0(:));xv=double(xv0(:));keep=isfinite(tv)&isfinite(xv);if(Ssel.enabled),keep&=gxtxt_selection_mask(Ssel,tv);endif;tp{end+1}=tv(keep);xp{end+1}=xv(keep);endif;if(C.eof),break;endif;endwhile unwind_protect_cleanup S=gxtxt_table_stream_close(S);end_unwind_protect;t=vertcat(tp{:});x=vertcat(xp{:});endfunction
function validate_selection(S,ds,tid),if(!strcmp(S.source_dataset_id,ds)),error('analysis.envelope_spectrum: Selection belongs to another Dataset');endif;if(!strcmp(S.type,'x_range')),error('analysis.envelope_spectrum: only x_range Selection is supported');endif;if(!isempty(S.x_variable_id)&&!strcmp(S.x_variable_id,tid)),error('analysis.envelope_spectrum: Selection targets another temporal variable');endif;endfunction
function s=binding_name(s),s=strtrim(s);p=strfind(s,'.');if(!isempty(p)),s=s(p(end)+1:end);endif;endfunction
function require_meta(m,label,module_id),if(!isfield(m,'found')||!m.found||!isfield(m,'variable_id')||isempty(strtrim(m.variable_id))),error('%s: %s binding could not resolve to stable variable_id',module_id,label);endif;endfunction
function s=find_schema(schema,id),s=[];for i=1:numel(schema),if(strcmp(strtrim(schema(i).variable_id),id)),s=schema(i);return;endif;endfor;endfunction
function s=make_psd_unit(u),u=strtrim(u);if(isempty(u)||strcmp(u,'1')),s='1/Hz';else s=[u '^2/Hz'];endif;endfunction
function s=safe_id(s),s=regexprep(strtrim(s),'[^A-Za-z0-9_.-]+','_');if(isempty(s)),s='signal';endif;endfunction
function write_report(path,ver,D,src_provider,spectrum_provider,envelope_provider,S,spectrum_result,envelope_result),fid=fopen(path,'w');if(fid<0),error('analysis.envelope_spectrum: cannot write report');endif;unwind_protect fprintf(fid,'Envelope Spectrum & Demodulation Analysis\nVersion: %s\n\nSource Dataset: %s\nSignal variable: %s (%s)\nSamples: %d\nSampling rate: %.17g Hz\nNFFT: %d\nFrequency spacing: %.17g Hz\nInput detrend: %s\nDemodulation filter: %s\nBand: %.17g .. %.17g Hz\nEnvelope DC: %s\nSpectrum window: %s\nEnvelope mean: %.17g %s\nEnvelope RMS: %.17g %s\nSource provider: %s\nSpectrum provider: %s\nEnvelope provider: %s\nSpectrum Dataset: %s\nEnvelope Dataset: %s\nSelection: %s\n',ver,D.source_dataset_id,D.signal_name,D.signal_variable_id,D.sample_count,D.fs,D.nfft,D.df,D.input_detrend,D.filter_mode,D.band_low_hz,D.band_high_hz,D.envelope_dc,D.window_name,D.envelope_mean,D.signal_unit,D.envelope_rms,D.signal_unit,src_provider,spectrum_provider,envelope_provider,D.spectrum_dataset_id,D.envelope_dataset_id,selection_name(S));unwind_protect_cleanup fclose(fid);end_unwind_protect;endfunction
function s=selection_name(S),if(isfield(S,'enabled')&&S.enabled),s=S.id;else s='none';endif;endfunction
function s=axis_label(name,unit),if(isempty(strtrim(unit))||strcmp(unit,'1')),s=name;else s=sprintf('%s [%s]',name,unit);endif;endfunction
function s=ini_escape(s),s=strrep(strrep(char(s),sprintf('\r'),' '),sprintf('\n'),' ');endfunction
function out=split_list(s),s=strrep(char(s),',',';');parts=strsplit(s,';');out={};for i=1:numel(parts),q=strtrim(parts{i});if(!isempty(q)),out{end+1}=q;endif;endfor;endfunction
function v=arg_value(args,key,def),v=def;for i=1:(numel(args)-1),if(strcmp(args{i},key)),v=args{i+1};return;endif;endfor;endfunction
